def book_combinations(total, a_per_box=5, b_per_box=7, c_per_box=9, error_tolerance=0):
    """
    return all integer compartments (a_compartments, b_compartments, c_compartments)
    satisfying:
        - a_compartments ∈ {0, 1, ..., 3}
        - b_compartments ∈ {0, 1, ..., 3}
        - c_compartments ∈ {0, 1, ..., 3}
        - (error_tolerance − max(0, total − 5*a_compartments − 7*b_compartments − 9*c_compartments)) == 0

    for total == 86 and error_tolerance == 0, this returns no solutions.
    for exact book counts without the balance constraint, return all nonnegative
    integer solutions to 5a + 7b + 9c == total.
    """
    a_max = 4 + 2 * error_tolerance // a_per_box
    b_max = 4 + 2 * error_tolerance // b_per_box
    c_max = 4 + 2 * error_tolerance // c_per_box

    solutions = []
    for a_compartments in range(a_max + 1):
        for b_compartments in range(b_max + 1):
            for c_compartments in range(c_max + 1):
                books = (
                    a_per_box * a_compartments
                    + b_per_box * b_compartments
                    + c_per_box * c_compartments
                )
                # allow only nonnegative shortages of at most the tolerance.
                if books <= total <= books + error_tolerance:
                    solutions.append((a_compartments, b_compartments, c_compartments))

    if not solutions and error_tolerance == 0:
        raise ValueError(
            f"exact book requirement of {total} boxes is not possible under the given compartment limits."
        )

    return solutions

