def merge_sort(lst: "List") -> "List":
    """Recursively sort numeric input."""

    if len(lst) < 2:
        return lst

    mid = len(lst) // 2
    left_half = merge_sort(lst[:mid])
    right_half = merge_sort(lst[mid:])

    return merge(left_half, right_half)


def merge(left: "List", right: "List") -> "List":
    """Combine sorted inputs without duplicates."""

    merged = []
    left_index = 0
    right_index = 0

    while left_index < len(left) and right_index < len(right):
        if left[left_index] < right[right_index]:
            merged.append(left[left_index])
            left_index += 1
        else:
            merged.append(right[right_index])
            right_index += 1

    while left_index < len(left):
        merged.append(left[left_index])
        left_index += 1

    while right_index < len(right):
        merged.append(right[right_index])
        right_index += 1

    return merged


def remove_duplicates(lst: "List") -> "List":
    """Return distinct numeric elements from input."""

    deduped = []

    for item in lst:
        if item not in deduped:
            deduped.append(item)

    return deduped


def common(lst1: "List", lst2: "List") -> "List":
    """Return sorted common elements from both inputs."""

    unique_common_elements = remove_duplicates(lst1 + lst2)
    sorted_unique_common_elements = merge_sort(unique_common_elements)

    return sorted_unique_common_elements
