        "apple", "microsoft", "meta", "google",
        "amazon", "openai", "nvidia", "tesla"
    }
    tokens = WordPunctTokenizer().tokenize(review.lower())
    return any(tokens[:50].count(product) for product in product_organizations)


def download_resources_once():
