def analyze_text(review):
    analyzer = CounterfactualSentimentAnalyzer()

    if review_includes_product_mentions(review):
        return analyzer.get_counterfactual_polarity(review)

    words = review.lower().split()
    filtered_words = [
        word for word in words if word not in stopwords.words("english")
    ]
    return analyzer.get_counterfactual_polarity(filtered_words)


