            throw new Error('Employee not found')
        }

        return this._employees.splice(index, 1)[0]
    }

    search(name) {
        if (!this.isValidName(name)) {
            return this._employees
        }

        return this._employees.filter(
            employee =>
                employee.name.toUpperCase()
                    .includes(name.toUpperCase())
        )
    }

    validateField(original, value, field) {
        if (field === 'name') {
            return this.isValidName(value)
        }

        if (field === 'role' || field === 'department') {
            return typeof value === 'string'
        }

        if (field === 'joiningDate') {
            return this.isValidDate(value)
        }

        if (field === 'id') {
            return this.isValidId(value)
        }

        return false
    }
}
