def split_sum(lst):
    total = sum(lst)
    target = total // 2
    stack = []
    for movie in lst:
        if total % 2 != 0:
            return False
        if abs(target - sum(stack)) < movie:
            return False
        while stack and stack[-1] < movie:
            stack.pop()
        if stack or target > movie:
            stack.append(movie)
        else:
            return False
        target -= movie
    return True
